// Valida token, device_id, chave e faixa. As faixas espelham hermes/mcp/comandos.py e
// firmware/lib/elex_core/settings.cpp: mudou uma, confira as outras.
const crypto = require('crypto');
const COMANDOS = {
  threshold: [0.3, 0.99],
  doa_enabled: null,
  motor_enabled: null,
  port1_skew: [-8, 8],
  motor_max_ms: [100, 2000],
};
const item = $input.first().json;
const recebido = String((item.headers || {})['x-elex-token'] || '');
const esperado = String($env.N8N_COMMAND_TOKEN || '');
const a = Buffer.from(recebido), b = Buffer.from(esperado);
if (!esperado || a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return [{ json: { ok: false, status: 401, erro: 'não autorizado' } }];
}
const p = item.body || {};
const key = String(p.key || '');
const value = p.value;
if (!/^[A-Za-z0-9._-]{1,64}$/.test(String(p.device_id || ''))) return [{ json: { ok: false, status: 400, erro: 'device_id inválido' } }];
if (!Object.prototype.hasOwnProperty.call(COMANDOS, key)) return [{ json: { ok: false, status: 400, erro: 'comando desconhecido' } }];
if (typeof value !== 'number' || !Number.isFinite(value)) return [{ json: { ok: false, status: 400, erro: 'valor inválido' } }];
const faixa = COMANDOS[key];
if (faixa === null ? !(value === 0 || value === 1) : !(value >= faixa[0] && value <= faixa[1])) {
  return [{ json: { ok: false, status: 400, erro: 'valor fora da faixa' } }];
}
return [{ json: { ok: true, status: 200, device_id: p.device_id, payload: JSON.stringify({ key, value }) } }];
